import { createHash } from 'node:crypto'

/**
 * Room addressing.
 *
 * - Editors connect to `/r/<roomId>`; the room id is a 128-bit random value
 *   generated by the client (base64url, 22 chars) and acts as the edit capability.
 * - Viewers connect to `/v/<viewId>` where `viewId = base64url(sha256("pano:view:" + roomId))`.
 *
 * Both resolve to the same internal key (the view id), so the server never needs
 * a secret and never stores raw room ids: knowing a view id does not reveal the
 * room id (pre-image resistance), so a read-only link cannot be upgraded.
 */
export const ROOM_ID_PATTERN = /^[A-Za-z0-9_-]{16,64}$/
export const VIEW_ID_PATTERN = /^[A-Za-z0-9_-]{43}$/

export interface RoomAddress {
  /** Internal key used for memory + storage (equals the view id). */
  key: string
  readOnly: boolean
}

export const viewIdFor = (roomId: string): string =>
  createHash('sha256').update(`pano:view:${roomId}`).digest('base64url')

export const parseRoomPath = (pathname: string): RoomAddress | null => {
  const match = /^\/(r|v)\/([^/]+)\/?$/.exec(pathname)
  if (!match) return null
  const [, kind, id] = match
  if (kind === 'r') {
    if (!ROOM_ID_PATTERN.test(id)) return null
    return { key: viewIdFor(id), readOnly: false }
  }
  if (!VIEW_ID_PATTERN.test(id)) return null
  return { key: id, readOnly: true }
}

/** Shortened key for logs: enough to correlate, not enough to open the room. */
export const logKey = (key: string): string => key.slice(0, 8)
